## 5. 限流设计

### 5.1 令牌桶

```go
// 令牌桶实现
type TokenBucket struct {
    tokens     float64
    maxTokens  float64
    rate       float64 // 每秒补充
    lastTime   time.Time
    mu         sync.Mutex
}

func (tb *TokenBucket) Allow() bool {
    tb.mu.Lock()
    defer tb.mu.Unlock()

    now := time.Now()
    tb.tokens += rate * now.Sub(tb.lastTime).Seconds()
    if tb.tokens > tb.maxTokens {
        tb.tokens = tb.maxTokens
    }
    tb.lastTime = now

    if tb.tokens >= 1 {
        tb.tokens -= 1
        return true
    }
    return false
}
```

### 5.2 滑动窗口

```go
// 滑动窗口实现
type SlidingWindow struct {
    windowSize time.Duration
    maxRequests int
    records []Record
    mu sync.Mutex
}

type Record struct {
    timestamp time.Time
    count int
}

func (sw *SlidingWindow) Allow() bool {
    sw.mu.Lock()
    defer sw.mu.Unlock()

    now := time.Now()
    cutoff := now.Add(-sw.windowSize)

    // 清理过期记录
    valid := make([]Record, 0)
    total := 0
    for _, r := range sw.records {
        if r.timestamp.After(cutoff) {
            valid = append(valid, r)
            total += r.count
        }
    }
    sw.records = valid

    if total >= sw.maxRequests {
        return false
    }

    sw.records = append(sw.records, Record{now, 1})
    return true
}
```

